fun testEventBus() {
    // -- tagsMatch: containment, kinds, empty --
    val tags = listOf(
        Eventbus.tagString(Tag.TOPIC, "orders"),
        Eventbus.tagInt(Tag.KIND, 5))
    checkEb(Eventbus.tagsMatch(tags, listOf()), "empty filter matches")
    checkEb(Eventbus.tagsMatch(tags,
        listOf(Eventbus.tagString(Tag.TOPIC, "orders"))), "containment")
    checkEb(Eventbus.tagsMatch(tags, tags), "self match")
    checkEb(!Eventbus.tagsMatch(tags,
        listOf(Eventbus.tagEnum(Tag.KIND, 5))), "int != enum")
    checkEb(!Eventbus.tagsMatch(tags,
        listOf(Eventbus.tagString(Tag.KIND, "5"))), "int != string")
    checkEb(!Eventbus.tagsMatch(tags,
        listOf(Eventbus.tagString(Tag.TOPIC, "other"))), "value mismatch")

    // -- fan-out honors filters --
    val (broker, client) = setupBus()
    val orders = ArrayList<Event>()
    val all = ArrayList<Event>()
    collect(Eventbus.subscribeEvents(client,
        listOf(Eventbus.tagString(Tag.TOPIC, "orders"))), orders)
    collect(Eventbus.subscribeEvents(client, listOf()), all)
    waitForEb({ broker.stats()["subscribers"] == 2L }, "2 subscribers")
    checkEb(Eventbus.publishEvent(client,
        listOf(Eventbus.tagString(Tag.TOPIC, "orders")), bytes("o1"), "test") == 1L,
        "seq 1")
    checkEb(Eventbus.publishEvent(client,
        listOf(Eventbus.tagString(Tag.TOPIC, "other")), bytes("x1"), "test") == 2L,
        "seq 2")
    waitForEb({ orders.size == 1 && all.size == 2 }, "fanout")
    checkEb(text(orders[0].payload) == "o1", "filtered payload")
    checkEb(orders[0].publisherId == "test", "publisher")
    checkEb(all[0].seq == 1uL && all[1].seq == 2uL, "all seqs")

    // -- kinds never cross-match --
    val (broker2, client2) = setupBus()
    val got = ArrayList<Event>()
    collect(Eventbus.subscribeEvents(client2,
        listOf(Eventbus.tagInt(Tag.KIND, 5))), got)
    waitForEb({ broker2.stats()["subscribers"] == 1L }, "kind subscriber")
    Eventbus.publishEvent(client2,
        listOf(Eventbus.tagString(Tag.KIND, "5")), bytes("s"), "")
    Eventbus.publishEvent(client2,
        listOf(Eventbus.tagEnum(Tag.KIND, 5)), bytes("e"), "")
    checkEb(Eventbus.publishEvent(client2,
        listOf(Eventbus.tagInt(Tag.KIND, 5)), bytes("i"), "") == 3L, "seq 3")
    waitForEb({ got.size == 1 }, "kind match")
    checkEb(text(got[0].payload) == "i", "int kind only")

    // (No user-tag pass-through leg: the generated Tag is a
    // closed Kotlin enum; see Eventbus.kt. Own tags arrive by
    // regenerating from an extended events.proto copy.)

    // -- slow subscriber drops oldest --
    val broker4 = EventBusBroker(4)
    val sub = broker4.subscribeLocal(listOf())
    for (i in 1..6) broker4.publishEvent(listOf(), bytes("m" + i), "")
    checkEb(broker4.stats()["dropped"] == 2L, "dropped count")
    checkEb(sub.dropped == 2, "sub dropped")
    val seqs = ArrayList<ULong>()
    for (i in 0 until 4) seqs.add(sub.take()!!.seq)
    checkEb(seqs == listOf(3uL, 4uL, 5uL, 6uL), "kept newest: " + seqs)
    sub.close()
    checkEb(broker4.stats()["subscribers"] == 0L, "close unregisters")

    // -- close unsubscribes (RPC) --
    val (broker5, client5) = setupBus()
    val stream = Eventbus.subscribeEvents(client5, listOf())
    waitForEb({ broker5.stats()["subscribers"] == 1L }, "1 subscriber")
    Eventbus.publishEvent(client5, listOf(), bytes("a"), "")
    checkEb(text(stream.recv().payload) == "a", "recv before close")
    stream.close()
    Eventbus.publishEvent(client5, listOf(), bytes("b"), "")
    waitForEb({ broker5.stats()["subscribers"] == 0L }, "reaped")

    // -- git log round-trip + idempotent --
    val repo = Files.createTempDirectory("grpc-dc-eventbus-").toFile()
    val broker6 = EventBusBroker()
    val events = listOf(
        broker6.publishEvent(
            listOf(Eventbus.tagString(Tag.TOPIC, "orders")), bytes("o1"), "test"),
        broker6.publishEvent(
            listOf(Eventbus.tagString(Tag.TOPIC, "other")), bytes("x1"), "test"),
        broker6.publishEvent(
            listOf(Eventbus.tagString(Tag.TOPIC, "orders")), bytes("o2"), "test"))
    val head1 = EventbusGit.exportEvents(repo.path, events)
    checkEb(EventbusGit.gitText(repo.path,
        listOf("rev-list", "--count", "grpc-dc-events")) == "3", "commit count")
    checkEb(EventbusGit.exportEvents(repo.path, events) == head1, "idempotent re-export")
    val imported = EventbusGit.importEvents(repo.path)
    checkEb(imported.size == 3 && imported[0].seq == 1uL && imported[2].seq == 3uL,
        "import seqs")
    checkEb(text(imported[0].payload) == "o1" && text(imported[2].payload) == "o2",
        "import payloads")
    val filtered = EventbusGit.importEvents(repo.path, EventbusGit.EVENT_LOG_BRANCH,
        0, null, listOf(Eventbus.tagString(Tag.TOPIC, "orders")))
    checkEb(filtered.size == 2 && filtered[1].seq == 3uL, "import filter")
    val window = EventbusGit.importEvents(repo.path, EventbusGit.EVENT_LOG_BRANCH,
        1, 2, null)
    checkEb(window.size == 1 && window[0].seq == 2uL, "import window")

    println("TestEventBus OK")
}
